<?php require_once __DIR__.'/config.php';if(user()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$found=null;foreach(data_load('users.json') as $x)if(strtolower($x['email'])===$email)$found=$x;if(!$found||!password_verify($pass,$found['password_hash']))$err='Неверный E-mail или пароль.';elseif(empty($found['email_verified']))$err='Сначала подтвердите E-mail.';else{$_SESSION['uid']=$found['id'];header('Location:index.php');exit;}}?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Вход — GREFFRLEND</title><link rel="stylesheet" href="style.css"></head><body><main class="wrap"><div class="card form" style="margin:70px auto"><a class="logo" href="index.php">GREFFRLEND</a><h1>Вход</h1><?php if($err):?><div class="card danger"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>E-mail</label><input type="email" name="email" required><label>Пароль</label><input type="password" name="password" required><button class="btn">Войти</button></form><p><a href="register.php">Создать аккаунт</a></p></div></main></body></html>